class LazySegmentTree:
    """Range-add and range-sum for a non-empty numeric list; intervals are inclusive."""
    def __init__(self, values):
        if not values: raise ValueError("values must not be empty")
        self.n=len(values); self.tree=[0]*(4*self.n); self.lazy=[0]*(4*self.n)
        self._build(1,0,self.n-1,values)
    def _build(self,node,left,right,a):
        if left==right: self.tree[node]=a[left]; return
        mid=(left+right)//2; self._build(node*2,left,mid,a); self._build(node*2+1,mid+1,right,a)
        self.tree[node]=self.tree[node*2]+self.tree[node*2+1]
    def _apply(self,node,left,right,delta):
        self.tree[node]+=(right-left+1)*delta; self.lazy[node]+=delta
    def _push(self,node,left,right):
        if self.lazy[node] and left<right:
            mid=(left+right)//2; d=self.lazy[node]
            self._apply(node*2,left,mid,d); self._apply(node*2+1,mid+1,right,d); self.lazy[node]=0
    def add(self,ql,qr,delta):
        if ql<0 or qr>=self.n or ql>qr: raise IndexError((ql,qr))
        self._add(1,0,self.n-1,ql,qr,delta)
    def _add(self,node,left,right,ql,qr,delta):
        if ql<=left and right<=qr: self._apply(node,left,right,delta); return
        self._push(node,left,right); mid=(left+right)//2
        if ql<=mid: self._add(node*2,left,mid,ql,qr,delta)
        if qr>mid: self._add(node*2+1,mid+1,right,ql,qr,delta)
        self.tree[node]=self.tree[node*2]+self.tree[node*2+1]
    def sum(self,ql,qr):
        if ql<0 or qr>=self.n or ql>qr: raise IndexError((ql,qr))
        return self._sum(1,0,self.n-1,ql,qr)
    def _sum(self,node,left,right,ql,qr):
        if ql<=left and right<=qr: return self.tree[node]
        self._push(node,left,right); mid=(left+right)//2; result=0
        if ql<=mid: result+=self._sum(node*2,left,mid,ql,qr)
        if qr>mid: result+=self._sum(node*2+1,mid+1,right,ql,qr)
        return result

